	private void resolveNestedVals(final JavacNode localNode, JCTree tree) {
		if (tree == null) return;
		tree.accept(new TreeScanner() {
			@Override public void visitVarDef(JCVariableDecl varDecl) {
				if (varDecl.vartype == null) return;
				String name = varDecl.vartype.toString();
				if (!eq(name, "val") && !eq(name, "var")) return;
				scanNestedVals(localNode, varDecl);
				JavacNode nestedNode = localNode.getNodeFor(varDecl);
				if (nestedNode == null || nestedNode.getKind() != lombok.core.AST.Kind.LOCAL) return;
				try {
					visitLocal(nestedNode, varDecl);
				} catch (Exception e) {
					// intentionally ignored; the regular traversal will process this declaration again and report any issues.
				}
			}

			@Override public void visitEnhancedForLoop(JCEnhancedForLoop loop) {
				scan(loop.expr);
				scan(loop.var);
				scan(loop.body);
			}
		});
	}

	private void scanNestedVals(final JavacNode localNode, final JCVariableDecl varDecl) {
		if (varDecl.init == null) return;
		varDecl.init.accept(new TreeScanner() {
			@Override public void visitVarDef(JCVariableDecl nested) {
				if (nested == varDecl) return;
				visitVarDef(nested);
			}

			@Override public void visitEnhancedForLoop(JCEnhancedForLoop loop) {
				scan(loop.expr);
				scan(loop.var);
				scan(loop.body);
			}
		});
	}
}

