	private void resolveNestedVals(final JavacNode localNode, JCTree tree) {
		if (tree == null) return;
		tree.accept(new TreeScanner<Void, Void>() {
			@Override public Void visitVarDef(JCVariableDecl varDecl) {
				scan(varDecl.init, null);
				if (varDecl.vartype == null) return null;
				String name = varDecl.vartype.toString();
				if (!eq(name, "val") && !eq(name, "var")) return null;
				JavacNode nestedNode = localNode.getNodeFor(varDecl);
				if (nestedNode == null || nestedNode.getKind() != lombok.core.AST.Kind.LOCAL) return null;
				try {
					visitLocal(nestedNode, varDecl);
				} catch (Exception e) {
					// intentionally ignored; the regular traversal will process this declaration again and report any issues.
				}
				return null;
			}

			@Override public Void visitEnhancedForLoop(JCEnhancedForLoop loop) {
				scan(loop.expr, null);
				scan(loop.var, null);
